let stored;
try { stored = JSON.parse(localStorage.getItem(storageKey) || 'null'); } catch { stored = null; }
const defaults = {profile:{name:'',bio:'',avatar:'',personalInterests:[],secondaryInterests:[],role:'attendee',topics:[],goals:['Meet people with shared interests'],open:true,visible:true},saved:[],custom:[],registrations:{},wallet:{},calendarPrefs:{provider:'apple',reminder:'none'},complete:false,stage:'before'};
let state = stored && typeof stored==='object' ? {...defaults,...stored,profile:{...defaults.profile,...stored.profile}} : structuredClone(defaults);
state.profile.topics=(Array.isArray(state.profile.topics)?state.profile.topics:[]).filter(id=>topics.some(t=>t.id===id)).slice(0,1);
state.profile.personalInterests=(Array.isArray(state.profile.personalInterests)?state.profile.personalInterests:[]).filter(id=>personalInterests.some(t=>t.id===id)).slice(0,2);
