function persist(){ try {localStorage.setItem(storageKey,JSON.stringify(state));}catch{toast('Your browser could not save changes.');} }
function events(){return [...sampleEvents,...state.custom.map(e=>({kind:'event',price:0,currency:'USD',interests:[],...e}))];}
function getEvent(id){return events().find(e=>e.id===id);}
function topic(id){return topics.find(t=>t.id===id)||topics[0];}
function personalTopics(){return state.profile.topics.map(topic);}
function btn(label,action,kind='',extra=''){return `<button class="btn ${kind}" ${extra} data-action="${action}">${label}</button>`;}
function navigate(to){if(sheet.open)sheet.close();route=to;location.hash=to;render();window.scrollTo({top:0,behavior:'instant'});}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2800);}
function brand(){return `<span class="brand"><img class="chi-header-logo" src="assets/identity/chi-2027.svg" alt="CHI 2027"><span class="sr-only">Conference companion</span></span>`;}

function badgeArt(){const [a]=personalTopics();return `<div class="personal-badge">${state.profile.avatar?`<img class="profile-photo" src="${esc(state.profile.avatar)}" alt="Your profile photo">`:icon(a?.icon||'identity-ai')}</div>`;}

function tags(ids){return `<div class="tag-row">${ids.map(id=>`<span class="pill">${icon(topic(id).icon)} ${esc(topic(id).name)}</span>`).join('')}</div>`;}
function eventCover(e, cls=''){
  const covers={matcha:['A little tea.','A lot to talk about.','coffee','01'],first:['First CHI?','You’re in good company.','people','02'],walk:['Take a breath.','Take a little walk.','walk','03'],ai:['Beyond','the prompt.','spark','04'],access:['Make room.','For everyone.','access','05'],play:['Less agenda.','More play.','game','06']};
  const [title,sub,mark,number]=covers[e.id]||[e.title,'A small gathering. A shared interest.',e.icon,'+'];
  return `<div class="gathering-cover cover-${esc(e.id in covers?e.id:'custom')} ${cls}" aria-hidden="true"><div class="cover-top"><span>CHI TOGETHER</span><span>№ ${number}</span></div><div class="cover-symbol">${icon(mark)}</div><div class="cover-type"><strong>${esc(title)}</strong><span>${esc(sub)}</span></div><div class="cover-foot"><span>COMMUNITY, IN PERSON.</span><span>PGH / 2027</span></div></div>`;
}
function hostIdentity(e){return `<span class="host-avatar">${esc(e.host.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><span><small>Hosted by</small><strong>${esc(e.host)}</strong></span>`;}
function welcome(){return `<div class="mobile-welcome"><header class="conference-masthead"><img src="assets/identity/chi-2027.svg" class="chi-wordmark" alt="CHI 2027"><p>A CONFERENCE FOR PEOPLE SHAPING<br>HUMAN–COMPUTER INTERACTION.</p></header><main><section class="onboarding-collage" aria-hidden="true">${[sampleEvents[0],sampleEvents[3],sampleEvents[1],sampleEvents[2],sampleEvents[5]].map((e,i)=>`<div class="collage-poster poster-${i}">${eventCover(e)}</div>`).join('')}<div class="collage-fade"></div></section><section class="mobile-welcome-copy"><p class="eyebrow">YOUR CONFERENCE COMPANION</p><h1>Shared interests.<br>Small gatherings.<br><span>Real connections.</span></h1><p>Find your people in the moments<br>between the big ideas.</p><button class="welcome-next" data-action="start" aria-label="Get started">${icon('arrow')}</button><button class="text-button" data-action="login">Already here? Log in ${icon('arrow')}</button><small>Independent prototype · CHI registration is separate.</small></section></main></div>`;}

function onboardShell(step,body,actions){return `<div class="wf-onboarding wf-step-${step} fade-in"><header class="wf-header"><button data-action="welcome" aria-label="Return to start">${brand()}</button><span class="wf-step-counter">${step} / 6</span></header><main class="wf-onboard-body"><div class="wf-question">${body}</div><div class="wf-onboard-actions">${actions}</div></main></div>`;}

function roleView(){return onboardShell(1,`<div class="wf-role-list">${[['attendee','calendar','Attendee','I’m attending CHI.','Find your people around sessions, shared interests and small gatherings.'],['visitor','people','Visitor','I’m here to explore.','Discover the community and activities open to visitors.']].map(([id,i,k,h,p])=>`<button class="wf-role-card ${state.profile.role===id?'selected':''}" aria-pressed="${state.profile.role===id}" data-role="${id}"><span class="row between"><span class="eyebrow">${k}</span><span class="check-circle">${state.profile.role===id?icon('check'):''}</span></span><span class="role-illustration">${icon(i)}</span><strong>${h}</strong><span class="role-description">${p}</span><span class="role-continue">Continue ${icon('arrow')}</span></button>`).join('')}</div>`,btn(`Continue ${icon('arrow')}`,'interests','wide')+`<button class="wf-back text-button" data-action="welcome" aria-label="Back">${icon('back')}</button>`);}

function interestsView(){return onboardShell(2,`<p class="eyebrow">A FIRST INTRODUCTION</p><h1>Let’s start<br>with your name.</h1><label class="form-label" for="profile-name">What should we call you?</label><input id="profile-name" class="input" autocomplete="given-name" maxlength="35" placeholder="Your first name" value="${esc(state.profile.name)}"><p class="demo-note" style="margin-top:14px">A name to help someone say hello.</p>`,btn(`Continue ${icon('arrow')}`,'goals','wide')+`<button class="wf-back text-button" data-action="role" aria-label="Back">${icon('back')}</button>`);}
function goalsView(){return onboardShell(3,`<p class="eyebrow">YOUR RESEARCH</p><h1>Domain interest</h1><p class="muted">Choose the one domain that best represents your research interests.</p><section class="question-section"><div class="question-section-heading"><span>Required · Choose 1</span></div><div class="interest-options wf-chips" role="radiogroup" aria-label="Your research domain">${topics.map(t=>`<button class="interest-option ${state.profile.topics.includes(t.id)?'selected':''}" role="radio" aria-checked="${state.profile.topics.includes(t.id)}" data-topic="${t.id}">${icon(t.icon)}<span>${t.name}</span></button>`).join('')}</div></section>`,btn(`Continue ${icon('arrow')}`,'secondary','wide',state.profile.topics.length?'':'disabled')+`<button class="wf-back text-button" data-action="interests" aria-label="Back">${icon('back')}</button>`);}
function secondaryView(){return onboardShell(4,`<p class="eyebrow">ROOM FOR ANOTHER PERSPECTIVE</p><h1>Secondary interest</h1><p class="muted">What else are you curious about in research?</p><section class="question-section"><div class="question-section-heading"><span>Optional · Choose up to 2</span></div><div class="interest-options wf-chips" aria-label="Secondary research interests">${topics.filter(t=>!state.profile.topics.includes(t.id)).map(t=>`<button class="interest-option ${state.profile.secondaryInterests.includes(t.id)?'selected':''}" aria-pressed="${state.profile.secondaryInterests.includes(t.id)}" data-secondary-interest="${t.id}">${icon(t.icon)}<span>${t.name}</span></button>`).join('')}</div><div class="selection-count">${state.profile.secondaryInterests.length} / 2 selected · You can continue without selecting.</div></section>`,btn(`Continue ${icon('arrow')}`,'outside','wide')+`<button class="wf-back text-button" data-action="goals" aria-label="Back">${icon('back')}</button>`);}
function outsideView(){return onboardShell(5,`<p class="eyebrow">A LITTLE MORE YOU</p><h1>Outside research</h1><p class="muted">Small interests can start good conversations, too.</p><section class="question-section"><div class="question-section-heading"><span>Optional · Choose up to 2</span></div><div class="interest-options wf-chips" aria-label="Personal interests">${personalInterests.map(t=>`<button class="interest-option ${state.profile.personalInterests.includes(t.id)?'selected':''}" aria-pressed="${state.profile.personalInterests.includes(t.id)}" data-personal-interest="${t.id}">${icon(t.icon)}<span>${t.name}</span></button>`).join('')}</div><div class="selection-count">${state.profile.personalInterests.length} / 2 selected</div></section>`,btn(`Create my profile ${icon('arrow')}`,'make-badge','wide')+`<button class="wf-back text-button" data-action="secondary" aria-label="Back">${icon('back')}</button>`);}

function badgeView(){return `<div class="profile-setup"><header class="profile-setup-top"><button class="icon-button" data-action="outside" aria-label="Back">${icon('back')}</button><button class="profile-done" data-action="finish" aria-label="Save profile and continue">${icon('check')}</button></header><main><div class="profile-introduction"><div class="profile-avatar-wrap">${badgeArt()}<button class="avatar-edit" data-action="change-avatar" aria-label="Choose a profile photo">${icon('plus')}</button><input id="avatar-file" type="file" accept="image/png,image/jpeg,image/webp" hidden></div><h1>Complete Your Profile</h1><p>Introduce yourself to others at CHI.</p></div><div class="profile-fields"><label class="form-label" for="profile-name">Your Name</label><input id="profile-name" class="input" autocomplete="given-name" placeholder="Your Name" maxlength="35" value="${esc(state.profile.name)}"><label class="form-label" for="profile-bio">Bio</label><textarea id="profile-bio" class="input" placeholder="Share a little about your background and interests." maxlength="240">${esc(state.profile.bio||'')}</textarea><p class="profile-selected-interest">${icon(personalTopics()[0]?.icon||'identity-ai')} ${esc(personalTopics()[0]?.name||'Your interest')}</p></div></main></div>`;}

