function shell(content,active='home'){return `<div class="shell wf-shell"><header class="wf-header"><button data-action="home" aria-label="CHI Together home">${brand()}</button><button class="wf-menu-toggle" data-action="menu" aria-label="Open menu"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M3 5h18M3 12h18M3 19h18"/></svg></button></header><main class="main fade-in" data-view="${active}">${content}</main></div>`;}
function menuView(){return `<div class="wf-menu fade-in"><header class="wf-header"><button data-action="home">${brand()}</button><button class="wf-menu-toggle" data-action="home" aria-label="Close menu">${icon('close')}</button></header><main><p class="eyebrow">YOUR CONFERENCE COMPANION</p><nav aria-label="Main navigation">${navItems.map(([r,i,l])=>`<button data-action="${r}">${icon(i)}<span>${l}</span>${icon('arrow')}</button>`).join('')}</nav>${btn(`${icon('plus')} Create event`,'create','wide')}<div class="wf-stage"><span>Conference view</span><div class="stage-control"><button data-stage="before" class="${state.stage==='before'?'active':''}" aria-pressed="${state.stage==='before'}">Before CHI</button><button data-stage="during" class="${state.stage==='during'?'active':''}" aria-pressed="${state.stage==='during'}">At CHI</button></div></div><p class="demo-note">Independent prototype · Demo activities</p></main></div>`;}

function intro(kicker,title,description,aside=''){return `<div class="page-intro"><p class="eyebrow">${kicker}</p><div class="row between"><h1>${title}</h1>${aside}</div>${description?`<p>${description}</p>`:''}</div>`;}
function eventCard(e){const saved=state.saved.includes(e.id);return `<article class="wf-list-event"><div class="wf-list-heading"><span>${icon(topic(e.topic).icon)} ${esc(topic(e.topic).name)}</span><button class="icon-button" data-save="${esc(e.id)}" aria-label="${saved?'Remove':'Save'} ${esc(e.title)}" aria-pressed="${saved}">${icon(saved?'check':'bookmark')}</button></div><button class="wf-list-content" data-event="${esc(e.id)}">${eventCover(e)}<span class="wf-list-facts"><span class="eyebrow">${esc(e.type)}</span><strong>${esc(e.title)}</strong><span>${icon('clock')} May ${e.day} · ${e.start}–${e.end}</span><span>${icon('pin')} ${esc(e.place)}</span><span class="list-price">${priceLabel(e)}</span><span class="wf-list-status">${e.status==='Full'?'Currently full':e.status==='Cancelled'?'Cancelled':e.kind==='paper'?'Conference session':'Registration required'} ${icon('arrow')}</span></span></button></article>`;}

function homeView(){const available=events().filter(e=>!['Cancelled','Full'].includes(e.status));const ranked=available.map((e,index)=>({e,index,score:(e.tags.some(t=>state.profile.topics.includes(t))?3:0)+(e.tags.some(t=>state.profile.secondaryInterests.includes(t))?1.5:0)+(e.interests||[]).filter(t=>state.profile.personalInterests.includes(t)).length})).sort((a,b)=>b.score-a.score||a.index-b.index);const recommended=(ranked[0]||{e:sampleEvents[0]}).e;const others=ranked.slice(1,5).map(x=>x.e);return shell(`<section class="wf-home-intro"><p class="eyebrow">${state.stage==='during'?'AT THE CONFERENCE':'YOUR CHI, A LITTLE MORE PERSONAL'}</p><h1>Hello, ${esc(state.profile.name||'Alex')}.</h1><p>A few good places to begin.</p></section><section class="planc-recommended" aria-label="Your top recommendation"><button class="planc-hero" data-event="${recommended.id}" aria-label="View recommended activity: ${esc(recommended.title)}">${eventCover(recommended)}<div class="planc-hero-copy"><span class="recommendation-label">${icon('spark')} PICKED FOR YOU</span><span class="hero-price">${priceLabel(recommended)}</span><h2>${esc(recommended.title)}</h2><span>May ${recommended.day} · ${recommended.start} ${icon('arrow')}</span></div></button></section><section class="planc-small-cards" aria-label="You might also like">${others.map(e=>`<button data-event="${esc(e.id)}"><span class="small-card-icon">${icon(e.icon)}</span><strong>${esc(e.title)}</strong><small>${priceLabel(e)} · May ${e.day}</small></button>`).join('')}</section><button class="planc-map-entry" data-action="map"><span class="map-entry-art" aria-hidden="true"><i></i><i></i><i></i>${icon('pin')}</span><span><small>A PLACE TO CONNECT</small><strong>See what’s gathering.</strong><span>Explore the map ${icon('arrow')}</span></span></button><section class="home-popular"><div class="home-section-heading"><div><p class="eyebrow">PITTSBURGH</p><h2>Popular gatherings</h2></div><button class="text-button" data-action="events" aria-label="See all activities">${icon('arrow')}</button></div><div class="popular-list">${available.filter(e=>e.kind!=='paper').slice(0,3).map(e=>compactEvent(e)).join('')}</div></section><section class="home-categories"><h2>Browse by domain</h2><div class="home-domain-grid">${topics.map(t=>`<button data-home-filter="${t.id}">${icon(t.icon)}<span>${t.name}</span></button>`).join('')}</div></section><section class="home-papers"><div class="home-section-heading"><h2>From the programme</h2><span class="pill">Example</span></div>${compactEvent(sampleEvents.find(e=>e.kind==='paper'))}</section>`);}

function filteredEvents(){return events().filter(e=>(filter==='all'||(filter==='saved'?state.saved.includes(e.id):e.tags.includes(filter)))&&(day==='all'||e.day===day)&&(!search||`${e.title} ${e.place} ${e.type} ${e.tags.map(t=>topic(t).name)}`.toLowerCase().includes(search.toLowerCase())));}
function resultsMarkup(){const result=filteredEvents();return result.length?result.map(eventCard).join(''):`<div class="empty">${icon('search')}<h3>No gatherings here just yet.</h3><p>Try another interest, a different day, or create a small gathering of your own.</p>${btn('Clear filters','clear-filters','secondary')}</div>`;}
function eventsView(){return shell(`<section class="wf-events-intro"><p class="eyebrow">DISCOVER</p><h1>Find your next gathering.</h1><div class="toolbar"><div class="search">${icon('search')}<input id="event-search" aria-label="Search activities" placeholder="Search activities and interests" value="${esc(search)}"></div></div></section><div class="filters" aria-label="Filter by interest">${[['all','All activities'],...topics.map(t=>[t.id,t.name]),['saved','Saved']].map(([id,n])=>`<button class="filter ${filter===id?'active':''}" aria-pressed="${filter===id}" data-filter="${id}">${n}</button>`).join('')}</div><div class="wf-event-list" id="event-results">${resultsMarkup()}</div><p class="demo-note">Example gatherings · Not the official CHI programme.</p>`,'events');}

function crowdMapArtwork(){return `<svg class="crowd-base-map" viewBox="0 0 800 1200" preserveAspectRatio="none" aria-hidden="true"><rect width="800" height="1200" fill="#eeeeee"/><g fill="#e8e8e8" stroke="#dcdcdc" stroke-width="2"><rect x="85" y="120" width="205" height="210" rx="35"/><rect x="420" y="95" width="260" height="160" rx="28"/><rect x="425" y="320" width="220" height="185" rx="27"/><rect x="80" y="445" width="215" height="235" rx="32"/><rect x="420" y="720" width="270" height="210" rx="30"/><rect x="95" y="850" width="210" height="185" rx="28"/></g><g stroke="#fafafa" fill="none" stroke-linecap="round"><path d="M350 0C325 200 375 315 350 525S340 850 370 1200" stroke-width="52"/><path d="M0 375C260 340 400 290 800 300M0 775C260 745 530 620 800 640M0 1100C250 1070 560 980 800 1000" stroke-width="38"/></g><g fill="none" stroke="#dddddd" stroke-width="2" stroke-dasharray="5 10"><path d="M350 0C325 200 375 315 350 525S340 850 370 1200"/><path d="M0 775C260 745 530 620 800 640"/></g><g font-family="Arial,sans-serif" font-size="18" fill="#bbbbbb" letter-spacing="1" text-anchor="middle"><text x="185" y="160">QUIET LOUNGE</text><text x="550" y="132">PAPER ROOMS</text><text x="535" y="355">CONVERSATIONS</text><text x="185" y="485">COFFEE CORNER</text><text x="555" y="760">SHARED TABLES</text><text x="190" y="890">HANDS-ON SPACE</text></g></svg>`;}
function visibleCrowdPeople(){return filterMapPeople(demoPeople,crowdState,state.profile);}
function mapView(){const people=visibleCrowdPeople();const groups=crowdGroups.map(g=>({...g,count:people.filter(p=>p.group===g.id).length})).filter(g=>g.count);const activityList=events().filter(e=>e.status!=='Cancelled'&&(crowdState.domain==='all'||e.tags.includes(crowdState.domain)));return shell(`<section class="crowd-map" data-level="${crowdState.zoom>=1.8?'people':'overview'}"><div class="crowd-viewport" tabindex="0" role="region" aria-label="Interactive example crowd map. Pinch or use zoom buttons to explore."><div class="crowd-world" style="--map-inverse:${1/crowdState.zoom}">${crowdMapArtwork()}<div class="crowd-heat-layer">${groups.map(g=>`<span class="crowd-heat" style="left:${g.x}%;top:${g.y}%;--heat-size:${80+g.count*4}px;--domain-shade:${g.shade}"></span>`).join('')}</div><div class="crowd-cluster-layer">${groups.map(g=>`<button class="crowd-cluster" data-crowd-group="${g.id}" style="left:${g.x}%;top:${g.y}%;--domain-shade:${g.shade}" aria-label="Explore ${esc(topic(g.topic).name)}, ${g.count} example people"><span class="cluster-symbol">${icon(topic(g.topic).icon)}<b>${g.count}</b></span><span class="cluster-domain-label">${esc(topic(g.topic).name)}</span></button>`).join('')}</div><div class="crowd-person-layer">${people.map(p=>`<button class="person-marker ${crowdState.selectedPerson===p.id?'selected':''}" data-crowd-person="${p.id}" aria-label="View ${esc(p.name)}, ${esc(topic(p.topic).name)}" aria-pressed="${crowdState.selectedPerson===p.id}" style="left:${p.x}%;top:${p.y}%;--domain-shade:${p.shade};--person-color:${p.color}"></button>`).join('')}</div>${crowdState.activities?`<div class="crowd-activity-layer">${activityList.map(e=>`<button class="crowd-event-pin" data-event="${esc(e.id)}" style="left:${e.x}%;top:${e.y}%" aria-label="Open gathering ${esc(e.title)}">${icon('calendar')}<small>${esc(e.title)}</small></button>`).join('')}</div>`:''}<span class="map-you-marker" style="left:50%;top:56%"><img src="assets/wireframe/location.svg" alt="Example reference point"><small>You · Example</small></span></div></div><div class="crowd-map-caption"><span class="map-stage-pill" data-map-level>${crowdState.zoom>=1.8?'Nearby people':'Crowd overview'}</span><p>${people.length} example people · ${groups.length} ${groups.length===1?'group':'groups'}</p><small data-map-hint>${crowdState.zoom>=1.8?'Tap a person to see their profile.':'Pinch or use + to explore the people in a group.'}</small></div>${!people.length?`<div class="crowd-empty">${crowdState.people?'No example people match these filters.':'People layer is hidden.'}<small>${crowdState.activities?'Activity pins are still available.':'Change the filters at the bottom left.'}</small></div>`:''}<div class="map-person-slot">${crowdPersonCard()}</div><details class="crowd-filters" ${crowdState.filtersOpen?'open':''}><summary>${icon('filter')} Filters <span>${crowdState.domain!=='all'||crowdState.shared?'•':''}</span></summary><div class="crowd-filter-panel"><h2>Show on the map</h2><label class="map-layer-choice"><span>${icon('people')} People</span><input type="checkbox" id="map-people" ${crowdState.people?'checked':''}></label><label class="map-layer-choice"><span>${icon('calendar')} Activities</span><input type="checkbox" id="map-activities" ${crowdState.activities?'checked':''}></label><label class="form-label" for="map-domain">Research domain</label><select class="select" id="map-domain"><option value="all">All domains</option>${topics.map(t=>`<option value="${t.id}" ${crowdState.domain===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><label class="map-layer-choice shared-map-choice"><span>Shared interests only</span><input type="checkbox" id="map-shared" ${crowdState.shared?'checked':''}></label><p>Matches your domain, secondary interests, or everyday interests.</p><div class="map-domain-key">${crowdGroups.map(g=>`<span><i style="background:${g.color}"></i>${icon(topic(g.topic).icon)}${esc(topic(g.topic).name)}</span>`).join('')}</div><button class="text-button" data-action="events">Browse activities ${icon('arrow')}</button></div></details><div class="crowd-zoom-controls" aria-label="Map zoom controls"><button data-crowd-action="zoom-in" aria-label="Zoom in">${icon('plus')}</button><span data-map-zoom-label>${crowdState.zoom.toFixed(1)}×</span><button data-crowd-action="zoom-out" aria-label="Zoom out" ${crowdState.zoom<=1?'disabled':''}><span aria-hidden="true">−</span></button><button class="map-recenter" data-crowd-action="reset" aria-label="Reset map view">${icon('pin')}</button></div><p class="crowd-map-disclaimer">Schematic spaces · Fictional people · No live location data</p></section>`,'map');}
function mutualCrowdInterests(person){const domains=[...state.profile.topics,...state.profile.secondaryInterests];return [...new Set([...domains.filter(id=>[person.topic,person.secondary].includes(id)).map(id=>topic(id).name),...state.profile.personalInterests.filter(id=>person.personalInterests.includes(id)).map(id=>personalInterests.find(t=>t.id===id)?.name).filter(Boolean)])];}
function crowdPersonCard(){const person=demoPeople.find(p=>p.id===crowdState.selectedPerson);if(!person||!visibleCrowdPeople().some(p=>p.id===person.id))return '';const shared=mutualCrowdInterests(person);return `<article class="map-person-card"><button class="person-card-close" data-crowd-action="close-person" aria-label="Close participant details">${icon('close')}</button><div class="person-card-heading"><span class="person-card-avatar" style="--domain-shade:${person.shade}">${icon(topic(person.topic).icon)}</span><div><h2>${esc(person.name)}</h2><p>${esc(person.role)} · Example participant</p></div></div><span class="person-domain">${icon(topic(person.topic).icon)}${esc(topic(person.topic).name)}</span><p class="person-card-shared">${shared.length?`Shared: ${shared.map(esc).join(' · ')}`:'A new perspective to discover.'}</p><button class="btn wide" data-crowd-profile="${person.id}">View profile ${icon('arrow')}</button></article>`;}
function refreshCrowdSelection(){const slot=document.querySelector('.map-person-slot');if(slot)slot.innerHTML=crowdPersonCard();document.querySelectorAll('[data-crowd-person]').forEach(node=>{const selected=node.dataset.crowdPerson===crowdState.selectedPerson;node.classList.toggle('selected',selected);node.setAttribute('aria-pressed',String(selected));});}
function showCrowdProfile(id){const person=demoPeople.find(p=>p.id===id);if(!person)return;const shared=mutualCrowdInterests(person);showSheet(`<div class="crowd-profile"><p class="eyebrow">FICTIONAL ATTENDEE · DEMO PROFILE</p><span class="person-profile-avatar" style="--domain-shade:${person.shade}">${icon(topic(person.topic).icon)}</span><h2>${esc(person.name)}</h2><p>${esc(person.role)} · ${esc(person.place)}</p><span class="pill">${icon(person.open?'chat':'people')}${person.open?'Open to a conversation':'Happy to join and listen'}</span><p class="form-label">DOMAIN INTEREST</p>${tags([person.topic])}<p class="form-label">SECONDARY INTEREST</p>${tags([person.secondary])}<p class="form-label">OUTSIDE RESEARCH</p><div class="tag-row">${person.personalInterests.map(id=>{const t=personalInterests.find(t=>t.id===id);return `<span class="pill">${icon(t.icon)}${esc(t.name)}</span>`;}).join('')}</div><p class="person-profile-bio">Curious about ${esc(topic(person.topic).name.toLowerCase())} and the ideas that come from meeting people with different perspectives.</p>${shared.length?`<div class="mutual-interests"><strong>A little common ground</strong><p>${shared.map(esc).join(' · ')}</p></div>`:''}<p class="form-label">A WAY TO SAY HELLO</p><div class="quote">“What’s one question you brought to CHI this year?”</div><p class="demo-note">An example profile for testing the map. No real person’s location or personal data is shown.</p></div>`,'Participant profile');}
function handleCrowdMapAction(el){if(el.dataset.crowdGroup){const group=crowdGroups.find(g=>g.id===el.dataset.crowdGroup);if(group){crowdState.selectedPerson=null;refreshCrowdSelection();crowdController?.focus(group.x,group.y,2.8);}return true;}if(el.dataset.crowdPerson){crowdState.selectedPerson=el.dataset.crowdPerson;refreshCrowdSelection();return true;}if(el.dataset.crowdProfile){showCrowdProfile(el.dataset.crowdProfile);return true;}if(el.dataset.crowdAction){switch(el.dataset.crowdAction){case'zoom-in':crowdController?.zoomIn();break;case'zoom-out':crowdController?.zoomOut();if(crowdState.zoom<1.8){crowdState.selectedPerson=null;refreshCrowdSelection();}break;case'reset':crowdState.selectedPerson=null;refreshCrowdSelection();crowdController?.reset();break;case'close-person':crowdState.selectedPerson=null;refreshCrowdSelection();break;}return true;}return false;}
document.addEventListener('change',event=>{const el=event.target;const field={'map-people':'people','map-activities':'activities','map-domain':'domain','map-shared':'shared'}[el.id];if(!field)return;crowdState[field]=el.id==='map-domain'?el.value:el.checked;crowdState.selectedPerson=null;render();});

function detailView(id){const e=getEvent(id);if(!e)return shell(`<div class="empty"><h2>This activity isn’t available.</h2>${btn('Browse activities','events')}</div>`,'events');const registration=state.registrations[id];const paper=e.kind==='paper';const closed=['Full','Cancelled'].includes(e.status);return shell(`<div class="event-detail"><div class="event-detail-toolbar"><button class="icon-button" data-action="home" aria-label="Back to home">${icon('back')}</button><button class="icon-button" data-share="${esc(id)}" aria-label="Share activity">${icon('share')}</button></div><div class="event-detail-cover">${eventCover(e)}<span>${paper?'EXAMPLE CHI PAPER SESSION':'FEATURED COMMUNITY GATHERING'}</span></div><div class="event-detail-heading"><p class="eyebrow">${esc(e.type)}</p><h1>${esc(e.title)}</h1><p class="detail-date">May ${e.day}, 2027 · ${e.start}–${e.end}<small>Pittsburgh time · EDT</small></p><span class="detail-price">${priceLabel(e)}</span></div><div class="event-action-row">${paper?`<button class="event-primary-action" data-calendar="${esc(id)}">${icon('calendar')}<span>Add to Calendar</span></button>`:registration?`<button class="event-primary-action" data-ticket="${esc(id)}">${icon('bookmark')}<span>My Ticket</span></button><button data-calendar="${esc(id)}">${icon('calendar')}<span>Calendar</span></button>`:`<button class="event-primary-action" data-register="${esc(id)}" ${closed?'disabled':''}>${icon('plus')}<span>${closed?esc(e.status):'Register'}</span></button>`}<button data-contact="${esc(id)}">${icon('chat')}<span>Contact</span></button><button data-event-more="${esc(id)}">${icon('more')}<span>More</span></button></div>${paper?'<p class="event-access-note">Included with conference access. No separate ticket or Wallet pass is issued.</p>':registration?'<p class="event-access-note">Registered in this prototype · Your demo ticket is ready.</p>':'<p class="event-access-note">Registration is required for all community events, including free events. Saving to your plan does not reserve a place.</p>'}<section class="event-location"><h2>Location</h2><strong>${esc(e.place)}</strong><button class="event-location-preview" data-locate="${esc(id)}">${icon('map')}<span>Find the meeting point</span>${icon('arrow')}</button></section><section class="event-about"><h2>About this ${paper?'session':'gathering'}</h2><p>${esc(e.description)}</p><p>${esc(e.expect)}</p><div class="event-host-block">${hostIdentity(e)}</div>${tags(e.tags)}<p class="demo-note">Illustrative content · ${paper?'Not an official programme entry.':'No real payment, booking or event communication takes place.'}</p></section></div>`,'events');}

function planView(){const list=events().filter(e=>state.saved.includes(e.id)).sort((a,b)=>Number(a.day)-Number(b.day)||a.start.localeCompare(b.start));const days=[...new Set(list.map(e=>e.day))];return shell(`${intro('Your conference, your pace','A little room for connection.','A personal plan. Not another packed schedule.')}<div class="row between" style="margin-bottom:28px"><span class="pill">${list.length} saved ${list.length===1?'activity':'activities'}</span>${btn(`${icon('plus')} Find a gathering`,'events','secondary')}</div>${list.length?days.map(d=>`<section class="plan-day"><div class="date-tile"><span>May</span><strong>${d}</strong><span>${['Mon','Tue','Wed','Thu','Fri'][Number(d)-10]||''}</span></div><div class="plan-list">${list.filter(e=>e.day===d).map(e=>`<article class="plan-item"><span class="plan-symbol">${icon(e.icon)}</span><button class="info" style="text-align:left" data-event="${esc(e.id)}"><small>${esc(e.start)}–${esc(e.end)} ${e.status==='Cancelled'?'· CANCELLED':''}</small><h3>${esc(e.title)}</h3><small>${esc(e.place)}</small>${state.registrations[e.id]?'<small class="plan-registration-label">Registered · Demo ticket</small>':''}</button><button class="icon-button" data-save="${esc(e.id)}" aria-label="Remove ${esc(e.title)} from plan">${icon('close')}</button></article>`).join('')}</div></section>`).join(''):`<div class="card empty">${icon('bookmark')}<h2>Leave a little space.<br>Then find something good.</h2><p>Save an activity when it catches your curiosity. You’ll find it here.</p>${btn('Explore activities','events')}</div>`}<p class="demo-note" style="margin:24px 0">Saved activities are stored in this browser. Saving does not reserve a place.</p>`,'plan');}
function profileView(){return shell(`${intro('Your shared-interest signal','A little about you.','A starting point for a conversation. Always on your terms.')}<div class="profile-layout"><div class="stack"><div class="badge-hero">${badgeArt()}<h2>${esc(state.profile.name||'Alex')}</h2><p>${personalTopics().map(t=>esc(t.name)).join(' × ')||'Curious about CHI'}</p>${state.profile.bio?`<p class="profile-bio-display">${esc(state.profile.bio)}</p>`:''}<span class="pill" style="position:relative;margin-top:18px;background:white">${icon(state.profile.open?'chat':'people')}${state.profile.open?'Open to a conversation':'Happy to join and listen'}</span></div>${btn(`${icon('share')} Show my badge`,'show-badge','secondary')}${btn(`${icon('download')} Download badge`,'download','outline')}</div><div class="stack"><div><p class="form-label" style="margin-top:0">MY DOMAIN</p><div class="settings-card">${personalTopics().map(t=>`<div class="group-row"><span class="row">${icon(t.icon)}${t.name}</span>${icon('check')}</div>`).join('')}<button class="group-row" style="width:100%;text-align:left" data-action="edit-interests">Edit interests ${icon('chevron')}</button></div></div><div><p class="form-label">MY PREFERENCES</p><div class="settings-card"><div class="group-row"><label for="profile-open">Open to a conversation<small>It’s okay to change your mind.</small></label><input id="profile-open" class="switch" type="checkbox" ${state.profile.open?'checked':''}></div><div class="group-row"><label for="profile-visible">Show interest badge<small>Your exact location stays private.</small></label><input id="profile-visible" class="switch" type="checkbox" ${state.profile.visible?'checked':''}></div><button class="group-row" style="width:100%;text-align:left" data-action="stage-toggle">Conference view <span class="muted small">${state.stage==='before'?'Before CHI':'At CHI'} ${icon('chevron')}</span></button></div></div><div><p class="form-label">LOOKING TO</p>${state.profile.goals.map(g=>`<p class="small muted" style="margin:8px 0">${icon('check')} ${esc(g)}</p>`).join('')}</div><button class="text-button small" style="align-self:flex-start" data-action="reset">${icon('reset')} Start the prototype again</button></div></div>`,'profile');}
function createView(){const d=draft||{title:'',day:'10',start:'12:30',end:'13:15',place:'',topic:state.profile.topics[0]||'health',capacity:'12',description:'',host:state.profile.name||'Alex'};return shell(`<div class="create-layout"><button class="text-button small row" data-action="events">${icon('back')} All activities</button><header class="create-intro"><h1>Create an event</h1><p>Bring people together around a shared interest.</p></header><form id="create-form"><div class="wf-create-cover">${eventCover({...sampleEvents[0],id:'custom',title:d.title||'Your next gathering',icon:'coffee'})}</div><div class="card"><p class="eyebrow">The essentials</p><label class="form-label" for="activity-title">Activity name</label><input id="activity-title" name="title" class="input" placeholder="e.g. Coffee & curious questions" required maxlength="80" value="${esc(d.title)}"><div class="form-row"><div><label class="form-label" for="activity-day">Day in May 2027</label><select id="activity-day" name="day" class="select">${['10','11','12','13','14'].map(x=>`<option value="${x}" ${d.day===x?'selected':''}>May ${x}</option>`).join('')}</select></div><div><label class="form-label" for="activity-capacity">Capacity</label><input id="activity-capacity" name="capacity" type="number" class="input" min="2" max="100" value="${esc(d.capacity)}" required></div></div><div class="form-row"><div><label class="form-label" for="activity-start">Starts</label><input id="activity-start" class="input" type="time" name="start" value="${esc(d.start)}" required></div><div><label class="form-label" for="activity-end">Ends</label><input id="activity-end" class="input" type="time" name="end" value="${esc(d.end)}" required></div></div><div class="recommendation-option"><label for="activity-recommendation"><span>Request CHI official recommendation</span><input id="activity-recommendation" name="recommendationRequested" type="checkbox" value="yes" ${d.recommendationRequested?'checked':''} aria-describedby="recommendation-help"></label><p id="recommendation-help">Optional. Requires review and approval before the event can appear as officially recommended by CHI.</p><small>Prototype only · No request is sent to CHI.</small></div><label class="form-label" for="activity-place">Meeting point</label><input id="activity-place" name="place" class="input" placeholder="A clear, permitted place to meet" required maxlength="100" value="${esc(d.place)}"><label class="form-label" for="activity-topic">Shared interest</label><select id="activity-topic" name="topic" class="select">${topics.map(t=>`<option value="${t.id}" ${d.topic===t.id?'selected':''}>${t.name}</option>`).join('')}</select><label class="form-label" for="activity-price">Ticket price (USD)</label><input id="activity-price" class="input" type="number" name="price" min="0" max="10000" step="0.01" value="${esc(d.price||0)}" required><p class="demo-note">Use 0 for a free activity. Paid tickets use the demo checkout.</p><label class="form-label" for="activity-description">What should people expect?</label><textarea id="activity-description" name="description" class="input" placeholder="A little about the conversation, who it’s for, and how to take part." required maxlength="800">${esc(d.description)}</textarea><div id="create-error" class="form-error" role="alert"></div><p class="demo-note">All activities require registration, including free events. Confirm permission to use the meeting space. This prototype saves activities locally and does not publish them to CHI.</p></div><div class="create-actions">${btn('Cancel','cancel-create','secondary')}<button type="submit" class="btn">Preview activity ${icon('arrow')}</button></div></form></div>`,'events');}
function render(){crowdController?.destroy();crowdController=null;document.title='CHI Together · '+(route.startsWith('event/')?'Activity':route==='welcome'?'A little more connected':route.charAt(0).toUpperCase()+route.slice(1));const views={welcome,role:roleView,interests:interestsView,goals:goalsView,secondary:secondaryView,outside:outsideView,badge:badgeView,login:loginView,home:homeView,menu:menuView,events:eventsView,map:mapView,plan:planView,profile:profileView,create:createView};app.innerHTML=route.startsWith('event/')?detailView(route.slice(6)):(views[route]||welcome)();const viewport=document.querySelector('.crowd-viewport');if(viewport)crowdController=mountCrowdMap(viewport,crowdState);}
function showSheet(content,title='Activity information'){sheet.setAttribute('aria-label',title);sheet.innerHTML=`<div class="sheet-header"><span class="eyebrow">CHI Together</span><button class="icon-button" data-action="close-sheet" aria-label="Close">${icon('close')}</button></div><div class="sheet-body">${content}</div>`;if(!sheet.open)sheet.showModal();}
function save(id){if(!getEvent(id))return;const exists=state.saved.includes(id);state.saved=exists?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(exists?'Removed from your plan':'Saved to your plan. No place reserved.');}
function showBadge(){if(!state.profile.visible){showSheet(`<h2>Your badge is private.</h2><p class="muted">You can make it visible in your badge preferences whenever you like.</p>${btn('Go to my badge','profile','wide')}`,'Private badge');return;}showSheet(`<div class="badge-hero">${badgeArt()}<h2>${esc(state.profile.name||'Alex')}</h2><p>${personalTopics().map(t=>esc(t.name)).join(' × ')}</p></div><p style="margin-top:22px;text-align:center" class="muted">${state.profile.open?'A shared interest is a good place to start.':'Happy to join and listen.'}</p>${btn('Download my badge','download','secondary wide')}`,'My interest badge');}
async function downloadBadge(){try{const selected=personalTopics()[0]||topics[0];const artwork=identitySymbols[selected.icon];const response=await fetch(`assets/identity/${artwork.src}`);if(!response.ok)throw new Error('Artwork unavailable');const blob=new Blob([await response.arrayBuffer()],{type:artwork.src.endsWith('.svg')?'image/svg+xml':'image/png'});const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});const source=`<svg xmlns="http://www.w3.org/2000/svg" width="600" height="760" viewBox="0 0 600 760"><rect width="600" height="760" rx="36" fill="#f5f5f5"/><text x="300" y="70" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="24" fill="#707070">CHI TOGETHER</text><svg x="225" y="155" width="150" height="150" viewBox="${artwork.view}" opacity=".65"><image href="${data}" width="${artwork.w}" height="${artwork.h}"/></svg><text x="300" y="405" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="38" fill="#606060">${esc(state.profile.name||'Hello')}</text><text x="300" y="460" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="22" fill="#777">${esc(selected.name)}</text><text x="300" y="690" text-anchor="middle" font-family="Helvetica,Arial,sans-serif" font-size="15" fill="#888">A shared interest is a place to begin.</text></svg>`;const url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml'}));const a=document.createElement('a');a.href=url;a.download='chi-interest-badge.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Your badge is ready to download.');}catch{toast('Your badge could not be downloaded. Please try again.');}}

function priceLabel(e){return e.kind==='paper'?'Conference access':Number(e.price)>0?`US$${Number(e.price).toFixed(2)}`:'Free · Registration required';}
function compactEvent(e){return `<button class="compact-event" data-event="${esc(e.id)}"><span class="compact-cover">${eventCover(e)}</span><span class="compact-info"><small>${esc(e.host)}</small><strong>${esc(e.title)}</strong><span>${icon('clock')} May ${e.day} · ${e.start}</span><em>${priceLabel(e)}</em></span></button>`;}
function tierOptions(e){return Number(e.price)>0?[{name:'Standard',price:Number(e.price),description:'One place at this gathering.'},{name:'Supporter',price:Number(e.price)+5,description:'One place, with an additional contribution to the gathering.'}]:[{name:'General admission',price:0,description:'One free place at this gathering.'}];}
function openRegistration(id){const e=getEvent(id);if(!e||e.kind==='paper'||['Full','Cancelled'].includes(e.status))return;if(state.registrations[id]){showTicket(id);return;}selectedTier=0;showTicketSelection(id);}
function showTicketSelection(id){const e=getEvent(id);if(!e)return;const tiers=tierOptions(e);showSheet(`<div class="registration-sheet"><h2>Select Ticket</h2><p class="sheet-event-name">${esc(e.title)}</p><div class="ticket-options" role="radiogroup" aria-label="Ticket type">${tiers.map((t,i)=>`<button role="radio" aria-checked="${selectedTier===i}" class="ticket-option ${selectedTier===i?'selected':''}" data-ticket-tier="${i}" data-registration-id="${esc(id)}"><span class="tier-circle">${selectedTier===i?icon('check'):''}</span><span><strong>${t.name}</strong><span class="tier-price">${t.price?`US$${t.price.toFixed(2)}`:'Free'}</span><small>${t.description}</small><small>May ${e.day} · ${e.start}–${e.end}</small></span></button>`).join('')}</div><p class="demo-note">Sample tickets · No real booking or payment.</p><button class="btn wide" data-registration-review="${esc(id)}">Next ${icon('arrow')}</button></div>`,'Select Ticket');}
function reviewRegistration(id){const e=getEvent(id);if(!e)return;const t=tierOptions(e)[selectedTier]||tierOptions(e)[0];showSheet(`<div class="registration-sheet"><p class="eyebrow">${t.price?'DEMO CHECKOUT':'CONFIRM YOUR PLACE'}</p><h2>${t.price?'Review your ticket.':'You’re one step away.'}</h2><div class="registration-summary"><strong>${esc(e.title)}</strong><span>May ${e.day} · ${e.start}–${e.end}</span><span>${esc(e.place)}</span><hr><span>${esc(t.name)} × 1</span><div class="row between"><strong>Total</strong><strong>${t.price?`US$${t.price.toFixed(2)}`:'Free'}</strong></div></div><p class="demo-note">${t.price?'This is a simulated payment. No card details are requested and you will not be charged.':'This prototype creates a demo ticket in this browser.'}</p><button class="btn wide" data-confirm-registration="${esc(id)}">${t.price?`Simulate payment · US$${t.price.toFixed(2)}`:'Confirm free registration'}</button><button class="text-button wide" data-registration-back="${esc(id)}">Back to ticket selection</button></div>`,t.price?'Demo checkout':'Confirm registration');}
function confirmDemoRegistration(id){const e=getEvent(id);if(!e||e.kind==='paper'||['Full','Cancelled'].includes(e.status))return;if(!state.registrations[id]){const t=tierOptions(e)[selectedTier]||tierOptions(e)[0];state.registrations[id]={code:'CHI-'+crypto.randomUUID().slice(0,8).toUpperCase(),tier:t.name,price:t.price,holder:state.profile.name||'Guest',registeredAt:new Date().toISOString()};if(!state.saved.includes(id))state.saved.push(id);persist();render();}showRegistrationSuccess(id);}
function showRegistrationSuccess(id){const e=getEvent(id);showSheet(`<div class="registration-success"><span class="registration-check">${icon('check')}</span><p class="eyebrow">DEMO REGISTRATION COMPLETE</p><h2>You’re on the list.</h2><p>${esc(e.title)}</p><p class="small muted">Your ticket is ready. Make a little room in your calendar.</p><button class="btn wide" data-calendar="${esc(id)}">${icon('calendar')} Add to Calendar</button><button class="btn secondary wide" data-wallet="${esc(id)}">${icon('bookmark')} Add to Wallet · Preview</button><button class="text-button wide" data-ticket="${esc(id)}">View my demo ticket ${icon('arrow')}</button></div>`,'Registration complete');}
function ticketMarkup(e,r){return `<div class="demo-ticket"><span class="eyebrow">CHI TOGETHER · DEMO TICKET</span><div class="ticket-mini-cover">${eventCover(e)}</div><h3>${esc(e.title)}</h3><p>May ${e.day} · ${e.start}–${e.end}</p><p>${esc(e.place)}</p><div class="ticket-perforation"></div><div class="ticket-holder"><span><small>GUEST</small><strong>${esc(r.holder)}</strong></span><span><small>${esc(r.tier)}</small><strong>${r.price?`US$${r.price.toFixed(2)}`:'Free'}</strong></span></div><code>${esc(r.code)}</code><small class="ticket-validity">Preview only · Not valid for admission.</small></div>`;}
function showTicket(id){const e=getEvent(id),r=state.registrations[id];if(!e||!r||e.kind==='paper')return;showSheet(`<h2>My Ticket</h2>${ticketMarkup(e,r)}<button class="btn wide" data-calendar="${esc(id)}">${icon('calendar')} Add to Calendar</button><button class="btn secondary wide" data-wallet="${esc(id)}">${icon('bookmark')} ${state.wallet[id]?'View demo Wallet pass':'Add to Wallet · Preview'}</button>`,'My Ticket');}
function showWallet(id){const e=getEvent(id),r=state.registrations[id];if(!e||!r||e.kind==='paper')return;showSheet(`<div class="wallet-preview"><p class="eyebrow">WALLET PREVIEW</p><h2>Your ticket, at hand.</h2>${ticketMarkup(e,r)}<p class="demo-note">This demonstrates a Wallet pass. It is saved only in the prototype, not in your device’s Wallet.</p><button class="btn wide" data-wallet-save="${esc(id)}">${state.wallet[id]?'Saved to demo wallet':'Save to demo wallet'}</button></div>`,'Wallet preview');}
function calendarActionMarkup(e){const p=state.calendarPrefs;return p.provider==='google'?`<a class="btn wide" href="${esc(googleCalendarUrl(e))}" target="_blank" rel="noopener noreferrer">Open Google Calendar ${icon('arrow')}</a><p class="demo-note">Choose your destination calendar and confirm the reminder in Google Calendar. This link opens an unsaved draft.</p><button class="btn secondary wide" data-calendar-download="${esc(e.id)}">Download .ics with selected reminder</button>`:`<button class="btn wide" data-calendar-download="${esc(e.id)}">Download calendar event ${icon('download')}</button><p class="demo-note">Open the .ics file in ${p.provider==='apple'?'Apple Calendar':'your calendar app'}, choose a destination calendar, and save it. The file includes your selected alert; your app may apply its own defaults.</p>`;}
function showCalendar(id){const e=getEvent(id);if(!e)return;showSheet(`<div class="calendar-sheet"><p class="eyebrow">MAKE A LITTLE ROOM</p><h2>Add to Calendar</h2><div class="calendar-event-summary"><strong>${esc(e.title)}</strong><span>May ${e.day} · ${e.start}–${e.end}</span><small>Pittsburgh time · EDT</small></div><label class="form-label" for="calendar-provider">Which calendar do you use?</label><select class="select" id="calendar-provider"><option value="apple" ${state.calendarPrefs.provider==='apple'?'selected':''}>Apple Calendar (.ics)</option><option value="google" ${state.calendarPrefs.provider==='google'?'selected':''}>Google Calendar</option><option value="other" ${state.calendarPrefs.provider==='other'?'selected':''}>Outlook / Other (.ics)</option></select><label class="form-label" for="calendar-reminder">Would you like a reminder?</label><select class="select" id="calendar-reminder">${[['none','No reminder'],['0','At start time'],['10','10 minutes before'],['30','30 minutes before'],['60','1 hour before'],['1440','1 day before']].map(([value,label])=>`<option value="${value}" ${String(state.calendarPrefs.reminder)===value?'selected':''}>${label}</option>`).join('')}</select><div id="calendar-action">${calendarActionMarkup(e)}</div></div>`,'Add to Calendar');sheet.dataset.calendarEvent=id;}
function exportCalendar(id){const e=getEvent(id);if(!e)return;const contents=buildCalendarFile(e,state.calendarPrefs.reminder);downloadArtifact(contents,'text/calendar;charset=utf-8',`chi-${e.id.replace(/[^a-z0-9-]/gi,'')}.ics`);if(!state.saved.includes(id)){state.saved.push(id);persist();render();}toast('Calendar file prepared. Open it in your calendar app to save.');}
function downloadArtifact(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function showShare(id){const e=getEvent(id);if(!e)return;const url=location.origin+location.pathname+'#event/'+encodeURIComponent(id);showSheet(`<div class="share-event-sheet"><h2>Share Event</h2><label class="share-link"><input aria-label="Event link" readonly value="${esc(url)}"><button class="icon-button" data-copy-event="${esc(id)}" aria-label="Copy event link">${icon('bookmark')}</button></label><div class="share-event-card">${eventCover(e)}<h3>${esc(e.title)}</h3><p>May ${e.day} · Pittsburgh</p><span>CHI Together</span></div><button class="btn wide" data-share-native="${esc(id)}">${icon('share')} Share Event</button><button class="text-button wide" data-copy-event="${esc(id)}">Copy link</button></div>`,'Share Event');}
async function copyEventLink(id){const url=location.origin+location.pathname+'#event/'+encodeURIComponent(id);try{await navigator.clipboard.writeText(url);toast('Event link copied.');}catch{sheet.querySelector('input')?.select();toast('Select and copy the event link above.');}}
function showEventMore(id){const e=getEvent(id);if(!e)return;showSheet(`<h2>A little more.</h2><div class="event-more-list"><button data-save="${esc(id)}">${icon('bookmark')}${state.saved.includes(id)?'Remove from my plan':'Save to my plan'}</button><button data-share="${esc(id)}">${icon('share')}Share event</button><button data-calendar="${esc(id)}">${icon('calendar')}Add to Calendar</button>${state.registrations[id]?`<button data-cancel-registration="${esc(id)}">${icon('close')}Cancel demo registration</button>`:''}</div>`,'Activity options');}
function handleEventWorkflow(el){
 if(el.dataset.save&&sheet.open){save(el.dataset.save);showEventMore(el.dataset.save);return true;}
 if(el.dataset.homeFilter){filter=el.dataset.homeFilter;search='';day='all';navigate('events');return true;}
 if(el.dataset.register){openRegistration(el.dataset.register);return true;}
 if(el.dataset.ticketTier!==undefined){selectedTier=Number(el.dataset.ticketTier);showTicketSelection(el.dataset.registrationId);return true;}
 if(el.dataset.registrationReview){reviewRegistration(el.dataset.registrationReview);return true;}
 if(el.dataset.registrationBack){showTicketSelection(el.dataset.registrationBack);return true;}
 if(el.dataset.confirmRegistration){confirmDemoRegistration(el.dataset.confirmRegistration);return true;}
 if(el.dataset.ticket){showTicket(el.dataset.ticket);return true;}
 if(el.dataset.calendar){showCalendar(el.dataset.calendar);return true;}
 if(el.dataset.calendarDownload){exportCalendar(el.dataset.calendarDownload);return true;}
 if(el.dataset.wallet){showWallet(el.dataset.wallet);return true;}
 if(el.dataset.walletSave){const id=el.dataset.walletSave;if(getEvent(id)?.kind==='paper'||!state.registrations[id])return true;state.wallet[id]={savedAt:new Date().toISOString()};persist();showWallet(id);toast('Saved in the demo wallet. Your device Wallet is unchanged.');return true;}
 if(el.dataset.share){showShare(el.dataset.share);return true;}
 if(el.dataset.copyEvent){copyEventLink(el.dataset.copyEvent);return true;}
 if(el.dataset.shareNative){const e=getEvent(el.dataset.shareNative);const url=location.origin+location.pathname+'#event/'+encodeURIComponent(e.id);if(navigator.share)navigator.share({title:e.title,text:'Join a gathering at CHI.',url}).catch(error=>{if(error.name!=='AbortError')copyEventLink(e.id);});else copyEventLink(e.id);return true;}
 if(el.dataset.eventMore){showEventMore(el.dataset.eventMore);return true;}
 if(el.dataset.contact){const e=getEvent(el.dataset.contact);showSheet(`<h2>Meet your host.</h2><div class="event-host-block">${hostIdentity(e)}</div><p class="detail-copy">Meeting point: ${esc(e.place)}.</p><p class="demo-note">Host messaging is not connected in this prototype.</p>`,'Contact host');return true;}
 if(el.dataset.cancelRegistration){const id=el.dataset.cancelRegistration;showSheet(`<h2>Cancel your demo ticket?</h2><p class="muted">This removes the registration and demo Wallet pass. Your personal plan is kept.</p><button class="btn wide" data-confirm-cancel-registration="${esc(id)}">Cancel demo registration</button><button class="btn secondary wide" data-ticket="${esc(id)}">Keep my ticket</button>`,'Cancel demo registration');return true;}
 if(el.dataset.confirmCancelRegistration){const id=el.dataset.confirmCancelRegistration;delete state.registrations[id];delete state.wallet[id];persist();sheet.close();render();toast('Demo registration cancelled.');return true;}
 return false;
}
document.addEventListener('change',event=>{const el=event.target;if(!['calendar-provider','calendar-reminder'].includes(el.id))return;state.calendarPrefs[el.id==='calendar-provider'?'provider':'reminder']=el.value;persist();const e=getEvent(sheet.dataset.calendarEvent);if(e)document.querySelector('#calendar-action').innerHTML=calendarActionMarkup(e);});

const actions={
  secondary:()=>{if(!state.profile.topics.length){toast('Choose a domain interest first.');return;}navigate('secondary');},outside:()=>navigate('outside'),
  start:()=>navigate('role'),welcome:()=>navigate('welcome'),role:()=>navigate('role'),interests:()=>navigate('interests'),
  goals:()=>{const input=document.querySelector('#profile-name');if(input){state.profile.name=input.value.trim();if(!state.profile.name){input.focus();input.setCustomValidity('Tell us what to call you.');input.reportValidity();return;}}persist();navigate('goals');},
  'make-badge':()=>{if(!state.profile.topics.length){toast('Choose at least one interest.');return;}const input=document.querySelector('#profile-name');if(input){state.profile.name=input.value.trim();if(!state.profile.name){input.focus();input.setCustomValidity('Tell us what to call you.');input.reportValidity();return;}}persist();navigate('badge');},
  'change-avatar':()=>document.querySelector('#avatar-file')?.click(),
  finish:()=>{const field=document.querySelector('#profile-name');if(field){state.profile.name=field.value.trim();if(!state.profile.name){field.setCustomValidity('Tell us what to call you.');field.reportValidity();field.focus();return;}}state.complete=true;persist();navigate(profileEdit?'profile':'home');profileEdit=false;},
  login:()=>navigate('login'),resume:()=>{if(!state.complete){state.profile={...state.profile,name:'Alex',topics:['health'],personalInterests:['coffee']};state.complete=true;persist();}navigate('home');},
  menu:()=>navigate('menu'),home:()=>navigate('home'),events:()=>navigate('events'),map:()=>navigate('map'),plan:()=>navigate('plan'),profile:()=>navigate('profile'),create:()=>navigate('create'),
  'edit-interests':()=>{profileEdit=true;navigate('goals');},'show-badge':showBadge,download:downloadBadge,
  'close-sheet':()=>sheet.close(),'clear-filters':()=>{search='';filter='all';day='all';render();},
  'stage-toggle':()=>{state.stage=state.stage==='before'?'during':'before';persist();render();},
  'cancel-create':()=>{draft=null;navigate('events');},
  publish:()=>{if(!draft)return;const t=topic(draft.topic);const item={...draft,id:'local-'+crypto.randomUUID(),type:'Community gathering',tags:[draft.topic],icon:t.icon,capacity:Number(draft.capacity),count:0,status:'Drop in',x:50,y:50,floor:1,local:true,expect:'Registration is required, including for free admission. Confirm meeting instructions and accessibility arrangements with the host.'};state.custom.push(item);state.saved.push(item.id);persist();draft=null;search='';filter='all';day='all';showSheet(`<div style="text-align:center"><div class="success-symbol">${icon('check')}</div><h2>A place to connect.</h2><p class="muted">Your sample activity has been added to Activities and your plan in this browser.</p>${btn('View my activity','published-view','wide',`data-id="${item.id}"`)}${btn('Keep exploring','events','secondary wide')}</div>`,'Activity created');},
  'published-view':el=>navigate('event/'+el.dataset.id),
  reset:()=>showSheet(`<h2>A fresh start?</h2><p class="muted">This clears your profile, saved activities and locally created gatherings from this browser.</p>${btn('Reset prototype','confirm-reset','wide')}${btn('Keep my progress','close-sheet','secondary wide')}`,'Reset prototype'),
  'confirm-reset':()=>{state=structuredClone(defaults);draft=null;persist();navigate('welcome');},
};
document.addEventListener('click',event=>{
  const el=event.target.closest('button, a');if(!el)return;
  if(handleCrowdMapAction(el))return;
  if(handleEventWorkflow(el))return;
  if(el.dataset.action){actions[el.dataset.action]?.(el);return;}
  if(el.dataset.role){state.profile.role=el.dataset.role;persist();navigate('interests');return;}
  if(el.dataset.personalInterest){const id=el.dataset.personalInterest;const list=state.profile.personalInterests;if(list.includes(id))state.profile.personalInterests=list.filter(t=>t!==id);else if(list.length<2)list.push(id);else{toast('Choose up to two personal interests.');return;}persist();render();document.querySelector(`[data-personal-interest="${id}"]`)?.focus({preventScroll:true});return;}
  if(el.dataset.secondaryInterest){const id=el.dataset.secondaryInterest;const selected=state.profile.secondaryInterests;if(selected.includes(id))state.profile.secondaryInterests=selected.filter(t=>t!==id);else if(selected.length<2)selected.push(id);else{toast('Choose up to two secondary interests.');return;}persist();render();document.querySelector(`[data-secondary-interest="${id}"]`)?.focus({preventScroll:true});return;}
  if(el.dataset.topic){state.profile.topics=[el.dataset.topic];state.profile.secondaryInterests=state.profile.secondaryInterests.filter(t=>t!==el.dataset.topic);persist();render();document.querySelector(`[data-topic="${el.dataset.topic}"]`)?.focus({preventScroll:true});return;}
  if(el.dataset.save){save(el.dataset.save);return;}
  if(el.dataset.event){navigate('event/'+el.dataset.event);return;}
  if(el.dataset.filter){filter=el.dataset.filter;render();return;}
  if(el.dataset.stage){state.stage=el.dataset.stage;persist();render();return;}
  if(el.dataset.floor){floor=Number(el.dataset.floor);render();return;}
  if(el.dataset.mapMode){mapMode=el.dataset.mapMode;render();return;}
  if(el.dataset.point){selectedPoint=el.dataset.point;mapMode='selected';render();return;}
  if(el.dataset.locate){const e=getEvent(el.dataset.locate);crowdState.activities=true;crowdState.focus={x:e.x,y:e.y,zoom:2.2};navigate('map');return;}
  if(el.dataset.cancel){const e=state.custom.find(x=>x.id===el.dataset.cancel);if(e){e.status=e.status==='Cancelled'?'Drop in':'Cancelled';persist();render();toast(e.status==='Cancelled'?'Activity marked as cancelled.':'Activity restored.');}return;}
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='avatar-file'){const file=el.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){toast('Choose a PNG, JPG or WebP image under 2 MB.');return;}const reader=new FileReader();reader.onload=()=>{state.profile.avatar=String(reader.result);persist();render();};reader.readAsDataURL(file);}if(el.dataset.goal){el.closest('.wf-goal')?.classList.toggle('selected',el.checked);state.profile.goals=el.checked?[...new Set([...state.profile.goals,el.dataset.goal])]:state.profile.goals.filter(g=>g!==el.dataset.goal);persist();}if(['open-chat','profile-open'].includes(el.id)){state.profile.open=el.checked;persist();if(el.id==='profile-open')render();}if(['badge-visible','profile-visible'].includes(el.id)){state.profile.visible=el.checked;persist();}if(el.id==='day-filter'){day=el.value;render();}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='profile-name'){el.setCustomValidity('');state.profile.name=el.value;persist();}if(el.id==='profile-bio'){state.profile.bio=el.value;persist();}if(el.id==='event-search'){search=el.value;document.querySelector('#event-results').innerHTML=resultsMarkup();}});
document.addEventListener('submit',event=>{if(event.target.id!=='create-form')return;event.preventDefault();const form=event.target;const values=Object.fromEntries(new FormData(form));const error=document.querySelector('#create-error');if(values.end<=values.start){error.textContent='The end time should be after the start time.';return;}if(!values.title.trim()||!values.place.trim()||!values.description.trim()){error.textContent='Add an activity name, meeting point, and description.';return;}draft={...values,recommendationRequested:values.recommendationRequested==='yes',recommendationStatus:values.recommendationRequested==='yes'?'pending':'not-requested',title:values.title.trim(),place:values.place.trim(),description:values.description.trim(),host:state.profile.name||'Alex'};showSheet(`<p class="eyebrow" style="margin-bottom:12px">Activity preview</p><h2>${esc(draft.title)}</h2><div class="info-row">${icon('clock')}<div><strong>May ${draft.day} · ${draft.start}–${draft.end}</strong><small>Pittsburgh time</small></div></div><div class="info-row">${icon('pin')}<div><strong>${esc(draft.place)}</strong><small>Capacity ${draft.capacity} · Registration required</small></div></div><p class="muted" style="margin:20px 0">${esc(draft.description)}</p>${tags([draft.topic])}<div class="recommendation-preview"><strong>${draft.recommendationRequested?'CHI recommendation · Pending approval (demo)':'CHI recommendation · Not requested'}</strong><p>${draft.recommendationRequested?'Review and approval are required before this event can be officially recommended. This prototype does not send a request to CHI.':'This event will remain a community activity.'}</p></div>${btn('Create sample activity','publish','wide')}${btn('Keep editing','close-sheet','secondary wide')}`,'Preview activity');});
sheet.addEventListener('click',event=>{if(event.target===sheet){const r=sheet.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)sheet.close();}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'welcome';if(next!==route){if(sheet.open)sheet.close();route=next;render();window.scrollTo(0,0);}});
render();
